import{z as i,x as s,o as e,c as l,q as r,j as t,D as E,d as B,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"因子分类学","description":"","frontmatter":{"title":"因子分类学","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fz-taxonomy.md","filePath":"quant/fz-taxonomy.md","lastUpdated":1791413859000}'),m={name:"quant/fz-taxonomy.md"};function h(d,a,p,u,c,F){const A=s("Mermaid");return e(),l("div",null,[a[2]||(a[2]=r('<h1 id="因子分类学" tabindex="-1">因子分类学 <a class="header-anchor" href="#因子分类学" aria-label="Permalink to &quot;因子分类学&quot;">​</a></h1><div class="epigraph"><p>数百个「已发表因子」要先落进少数几个家族，才有除重、配置与归因可言；地图不等于疆域，但没有地图，你会在同一块疆域上买三次。</p><footer>—— 据 Fama &amp; French, Journal of Financial Economics, 2015；Carhart, Journal of Finance, 1997；Asness, Moskowitz &amp; Pedersen, Journal of Finance, 2013 整理</footer></div><p><a href="/quant/fz-decay-lifecycle">上一课</a>把单个因子的生命周期写进治理。本课抬起视角：前四课的处理对象始终是「一个因子」，可实务里要管的是一张清单——文献里 t 统计量过 3.0 的候选以百计（<a href="/quant/harvey-liu-zhu">Harvey–Liu–Zhu</a>），机构内部的自研因子还要再加一层。没有分类，风险模型重复计暴露、归因把一笔收益算进三个因子、配置在同一个风格上买三份。本课写分类的两个维度、两张常用的正式地图、以及地图的使用规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分类的难点不是列家族，而是承认分类服务于决策：风险模型要用它去重，配置要用它分预算，归因要用它定名。三个用途对粒度的要求不同——风险模型要细到暴露不重复，配置要粗到家族间低相关。用一张图同时服务三个用途，就会要么太粗（重复配置）要么太细（预算碎片化）。更深一层：家族标签不是定价理论，「价值」是一个相关度高的组合集合，不回答溢价为什么存在；把地图当理论，是因子投资里最常见的滑坡。</p><h3 id="两个维度" tabindex="-1">两个维度 <a class="header-anchor" href="#两个维度" aria-label="Permalink to &quot;两个维度&quot;">​</a></h3><p><span class="marginnote">FF5 用盈利（RMW）与投资（CMA）扩充三因子后，HML 对其余因子回归的 α 不再显著；Carhart (1997) 的四因子则把动量列为与价值并列的独立轴。同一家公司在两张地图上的坐标不同——报告因子结果时先声明用哪张地图，坐标才有意义。</span></p><p>第一维度按溢价来源：风险补偿（承担别人不愿承担的，如低波动、部分价值）与行为错定价（错误定价被修正的过程，如动量、盈余公告后漂移）。这是先验标签不是判决：一个家族可以两者兼有。第二维度按现象学家族：价值（<a href="/quant/value-factors">价值因子</a>）、动量（截面<a href="/quant/momentum-wml">动量</a>与时序 <a href="/quant/tsmom">tsmom</a>）、carry（<a href="/quant/carry-everywhere">carry-everywhere</a>）、质量与盈利（<a href="/quant/qmj">qmj</a>、<a href="/quant/gross-profitability">盈利质量</a>）、投资（<a href="/quant/investment-factor">投资因子</a>）、低风险（<a href="/quant/low-vol-bab">低波与 BAB</a>）、规模、流动性（<a href="/quant/liquidity-factor">流动性因子</a>）。正式地图是模型：Fama–French 2015 的五因子（市场、规模、价值、盈利、投资）与 Carhart 1997 的四因子（加动量）是最常用的两张；Asness–Moskowitz–Pedersen 2013 则证明价值与动量在股票、债券、商品、外汇普遍存在，支持「家族」跨资产成立。</p>',8)),(e(),t(o,null,{default:E(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%9B%A0%E5%AD%90%E6%B8%85%E5%8D%95%EF%BC%88%E6%95%B0%E7%99%BE%EF%BC%89%22%5D%20--%3E%20MAP%5B%22%E5%88%86%E7%B1%BB%E5%9C%B0%E5%9B%BE%EF%BC%88%E7%89%88%E6%9C%AC%E5%9B%BA%E5%AE%9A%EF%BC%89%22%5D%0A%20%20MAP%20--%3E%20SRC%5B%22%E7%BB%B4%E5%BA%A6%E4%B8%80%EF%BC%9A%E6%BA%A2%E4%BB%B7%E6%9D%A5%E6%BA%90%EF%BC%88%E5%85%88%E9%AA%8C%E6%A0%87%E7%AD%BE%EF%BC%89%22%5D%0A%20%20MAP%20--%3E%20FAM%5B%22%E7%BB%B4%E5%BA%A6%E4%BA%8C%EF%BC%9A%E7%8E%B0%E8%B1%A1%E5%AD%A6%E5%AE%B6%E6%97%8F%22%5D%0A%20%20FAM%20--%3E%20VA%5B%22%E4%BB%B7%E5%80%BC%22%5D%0A%20%20FAM%20--%3E%20MO%5B%22%E5%8A%A8%E9%87%8F%22%5D%0A%20%20FAM%20--%3E%20CA%5B%22carry%22%5D%0A%20%20FAM%20--%3E%20QU%5B%22%E8%B4%A8%E9%87%8F%E4%B8%8E%E7%9B%88%E5%88%A9%22%5D%0A%20%20FAM%20--%3E%20LR%5B%22%E4%BD%8E%E9%A3%8E%E9%99%A9%2F%E8%A7%84%E6%A8%A1%2F%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20SRC%20--%3E%20CORR%5B%22%E5%AE%B6%E6%97%8F%E5%86%85%E9%AB%98%E7%9B%B8%E5%85%B3%E3%80%81%E5%AE%B6%E6%97%8F%E9%97%B4%E4%BD%8E%E7%9B%B8%E5%85%B3%22%5D%0A%20%20FAM%20--%3E%20CORR%0A%20%20CORR%20--%3E%20USE%5B%22%E5%8E%BB%E9%87%8D%2F%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%2F%E5%BD%92%E5%9B%A0%E5%AE%9A%E5%90%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>地图的使用规则有三条。</p><p><span class="marginnote">数字实例：风险预算按家族分块，意味着 20 个动量变体共享「动量」这一份预算，而不是各得二十分之一份再加总成一大份。常见误区恰好相反：按论文数配置，动量家族悄悄占掉预算表的六成——账面上分散在几十个策略，风险上其实是一笔仓位。</span>第一，新因子入账必须报坐标：相对哪张地图、落在哪个家族、家族内的正交化残差还剩多少——上一课的操作按家族做。第二，配置按家族不按论文：把相关矩阵按家族分块，家族内平均相关高、家族间低，风险预算按块分配。这是多策略平台把预算分给价值、动量、carry 各一份而不是给几十篇论文各一份的数学依据，也是<a href="/quant/risk-parity">风险平价</a>思路在因子层的用法。第三，警惕跨家族的伪装相关：质量与低波动在防御期同涨同跌，按家族是两份预算，按风险实际是一份——预算表要定期用已实现相关回查。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么家族划分有效？因为分类的底层是收益的共同驱动：同一家族的因子持有相似的股票、对相似的冲击敏感，所以家族内相关结构性偏高；不同家族的驱动不同——价值的均值回归、趋势的持续性、carry 的时限结构——家族间相关低。</p><p><span class="marginnote">直觉类比：分散化像水果篮——第 21 个苹果几乎不增加多样性，加一根香蕉才有意义。家族就是水果的种类：家族内再添成员（苹果换成不同产地），营养结构不变；家族间替换（苹果换香蕉）才改变整体的波动来源。分散化的收益按「块」计算，不按个数计算。</span></p>',6)),(e(),t(o,null,{default:E(()=>[n(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%8A%A8%E9%87%8F%E5%AE%B6%E6%97%8F%EF%BC%9A%E5%B7%B2%E6%9C%89%2020%20%E4%B8%AA%E5%8F%98%E4%BD%93%22%5D%20--%3E%20ADD%5B%22%E5%86%8D%E5%8A%A0%E5%85%A5%E4%B8%80%E4%B8%AA%E5%8A%A8%E9%87%8F%E5%9B%A0%E5%AD%90%22%5D%0A%20%20ADD%20--%3E%20RHO%5B%22%E4%B8%8E%E5%AE%B6%E6%97%8F%E5%86%85%E7%9B%B8%E5%85%B3%200.8-0.9%22%5D%0A%20%20RHO%20--%3E%20ZERO%5B%22%E5%88%86%E6%95%A3%E5%8C%96%E8%B4%A1%E7%8C%AE%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20C%5B%22carry%20%E5%AE%B6%E6%97%8F%22%5D%20--%3E%20ADD2%5B%22%E5%8A%A0%E5%85%A5%E4%B8%80%E4%B8%AA%20carry%20%E5%9B%A0%E5%AD%90%22%5D%0A%20%20ADD2%20--%3E%20LOW%5B%22%E4%B8%8E%E5%8A%A8%E9%87%8F%E5%AE%B6%E6%97%8F%E7%9B%B8%E5%85%B3%E4%BD%8E%22%5D%0A%20%20LOW%20--%3E%20GAIN%5B%22%E7%9C%9F%E6%AD%A3%E6%89%A9%E5%A4%A7%E5%88%86%E6%95%A3%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>分散化的收益来自低相关的块，而不是来自因子个数：往一个已有二十个动量变体的组合里再加第二十一个动量因子，分散化贡献接近零。这正是「地图决定边际价值」的先声，本课程后面会用正交化 IR 把它写成公式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分类学不回答存在性问题：家族标签不解释溢价来源，风险补偿与行为的划分常不可检验，只能作为先验声明写进报告。地图有版本问题：五因子与四因子的坐标不同，跨地图比较因子排名没有共同零假设；机构要固定自己的地图并记录版本。</p><p><span class="marginnote">常见误区：把家族标签当定价理论，以为说「这是价值因子」就解释了它为什么赚钱。「价值」只是一组相关度高的组合的集合名，像「鸟类」这个名字并不解释鸟为什么会飞。溢价来源（风险补偿还是行为）是另一个层面的声明，而且常常不可检验——地图的用途是去重与预算，不是因果解释。</span>本课给的是静态地图；家族收益随宏观状态移动——价值在复苏期、动量在衰退尾部——是条件化问题，留给下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分类服务三个决策：风险去重、风险预算、归因定名；粒度按用途选。</li><li>两个维度：溢价来源（先验标签）与现象学家族（可操作分组）。</li><li>正式地图固定为模型（FF5、Carhart 四因子），报告先报地图版本。</li><li>家族的统计基础是分块相关：家族内高、家族间低，分散化按块计算。</li><li>出处：Fama &amp; French, <em>JFE</em>, 2015；Carhart, <em>JF</em>, 1997；Asness, Moskowitz &amp; Pedersen, <em>JF</em>, 2013。</li></ul>',6))])}const C=i(m,[["render",h]]);export{f as __pageData,C as default};
